import re
p='public/index.html'; h=open(p,encoding='utf8').read()
def rep(o,n):
    global h
    assert h.count(o)==1,o[:60]; h=h.replace(o,n,1)
rep("['🌺', 'مريم عليها السلام']],","['🌺', 'مريم عليها السلام'], ['❤️', 'محبة المسلمين لعيسى ومريم والإيمان بهما']],")
items=[
 ('لا يكتمل إيمان المسلم إلا بالإيمان بعيسى وبجميع الرسل','المسلم يؤمن بعيسى وبجميع الأنبياء والرسل إيماناً لا يصحّ الإسلام بدونه، ولا يفرّق بين أحد منهم. ومن كفر برسل الله فقد ضلّ ضلالاً بعيداً.',['2:285','2:136','3:84','4:136','4:152']),
 ('نحب عيسى عليه السلام: عبد الله ورسوله وكلمته','نحب عيسى ونوقّره ونصلّي ونسلّم عليه كما نفعل مع سائر الأنبياء؛ فهو عبد الله ورسوله وكلمته ألقاها إلى مريم وروح منه، وجيه في الدنيا والآخرة ومن المقرّبين، ومن الصالحين.',['4:171','3:45','3:46','6:85']),
 ('أنبياء إخوة','ورد في الحديث الصحيح (البخاري ومسلم) قول النبي ﷺ: «أنا أولى الناس بعيسى ابن مريم في الدنيا والآخرة، والأنبياء إخوة لعلّات، أمهاتهم شتى ودينهم واحد».',[]),
 ('الشهادة التي تشمل عيسى','جاء في الصحيحين قوله ﷺ: «من شهد أن لا إله إلا الله وحده لا شريك له، وأن محمداً عبده ورسوله، وأن عيسى عبد الله ورسوله وكلمته ألقاها إلى مريم وروح منه، وأن الجنة حق والنار حق، أدخله الله الجنة على ما كان من العمل».',[]),
 ('السلام على عيسى','قال عيسى عليه السلام: «والسلام عليّ يوم ولدت ويوم أموت ويوم أبعث حياً»، وهو مبارك أينما كان، وأوصاه الله بالصلاة والزكاة ما دام حياً.',['19:33','19:31']),
 ('مريم الطاهرة المصطفاة بلا ذنب','لا يقول المسلم في مريم إلا خيراً: اصطفاها الله وطهّرها على نساء العالمين، وهي الصدّيقة القانتة التي أحصنت فرجها وصدّقت بكلمات ربها وكتبه، وبرّأها الله ممّا رماها به قومها.',['3:42','66:12','5:75','19:20']),
 ('حفظ الله لمريم وابنها من الشيطان','دعت أم مريم: «وإني أعيذها بك وذريتها من الشيطان الرجيم»، وجاء في الصحيحين أن النبي ﷺ قال: «ما من مولود إلا مسّه الشيطان حين يولد... إلا مريم وابنها»، فاستجاب الله دعاءها.',['3:36']),
]
js="".join("    { g: 4, t: '%s', note: '%s', keys: [%s] },\n"%(t,n,", ".join("'%s'"%k for k in ks)) for t,n,ks in items)
a=h.index("TOPICS.jesus = {"); b=h.index("  ],\n};",a)
h=h[:b]+js+h[b:]
open(p,'w',encoding='utf8').write(h)
m=re.search(r'<script type="module">([\s\S]*?)</script>',h).group(1)
open('tmp_check.mjs','w',encoding='utf8').write(re.sub(r'^import .*$','',m,flags=re.M))
